def icon(n): return f'<svg viewBox="0 0 24 24" aria-hidden="true">{icons[n]}</svg>'
def btn(action,text,ico='',cls=''): return f'<button type="button" data-action="{action}" class="{cls}">{icon(ico) if ico else ""}<span>{text}</span></button>'
def picker(label,items,action):
 return f'<details class="picker"><summary aria-label="{label}"><span>{items[0]}</span>{icon("chevron")}</summary><div class="pickmenu">'+''.join(btn(action,x) for x in items)+'</div></details>'
def cliplist():
 return '<div class="clip-items">'+''.join(f'<button class="clip {"is-selected" if i==0 else ""}" data-clip="{i}" aria-pressed="{"true" if i==0 else "false"}"><span class="order">{i+1:02}</span><span class="thumbnail"><img src="{poster}" alt="" style="object-position:{30+i*8}% center"><span class="duration">{d}</span></span><span class="clip-copy"><strong>{t}</strong><small>{k}</small><time>{tm}</time></span><span class="clip-star">{"☆" if not f else "★"}</span></button>' for i,(t,k,d,tm,f) in enumerate(clips))+'</div>'
def navigation():
 return f'<nav class="library-nav" aria-label="Library">{btn("all","All clips","film","active")}{btn("favorites","Favorites","star")}{btn("reels","Session reels","film")}</nav>'
def library():
 return f'<aside class="library"><div class="library-heading"><span>Today</span><span class="count">6 clips</span></div>{cliplist()}<div class="empty-results" hidden>No matching clips.<br>{btn("clear","Clear filters")}</div><div class="library-end">Saved on this computer</div></aside>'
def viewer():
 return f'''<main class="viewer">
<div class="view-heading"><div><p class="eyebrow">SELECTED MOMENT</p><h2 class="selected-title">Paperwork in orbit</h2><p class="meta selected-meta">Spectacular launch · Today, 9:42 PM · 0:15</p></div>{btn('favorite','Favorite','star','favorite-button')}</div>
<div class="screen"><img class="poster" src="{poster}" alt="Rat Detective gameplay: a rat carries a glowing case through the city"><button class="play-overlay" data-action="play" aria-label="Play selected clip">{icon('play')}</button><span class="screen-label">0:15</span><div class="state-message" hidden><strong></strong><p></p>{btn('retry','Try again')}</div></div>
<div class="transport">{btn('play','Play','play','play-button')}<span class="play-time">0:00</span><input class="seek" aria-label="Playback position" type="range" min="0" max="15" value="0"><span class="end-time">0:15</span>{btn('mute','Muted','volume','mute-button')}</div>
<div class="clip-actions">{btn('trim','Trim clip','scissors')}{btn('export','Export clip','export','primary')}<details class="picker more"><summary aria-label="More clip actions">{icon('more')}</summary><div class="pickmenu">{btn('rename','Rename clip')}{btn('reveal','Show in folder','folder')}{btn('delete','Move to trash','','danger')}</div></details></div>
<div class="edit-panel" hidden><div class="edit-title"><strong>Trim clip</strong>{btn('cancel-trim','Cancel')}</div><p class="meta">Set the start and end. Your original recording is kept.</p><div class="trim-track"><span></span></div><div class="trim-fields"><label>Start <input class="trim-start" type="number" min="0" max="14" value="0" step="0.1"> s</label><label>End <input class="trim-end" type="number" min="0.1" max="15" value="15" step="0.1"> s</label>{btn('apply-trim','Save trim','','primary')}</div></div>
<div class="reel-panel" hidden><div><strong>Today’s session reel</strong><p class="meta">6 moments · 1:53</p></div>{btn('regenerate','Refresh selection')}{btn('export-reel','Export reel','export','primary')}</div>
<div class="toast" role="status" hidden></div>
</main>'''
def window():
 return f'''<div class="app"><header class="app-header"><div class="brand">{icon('film')}<div><h1>Highlights</h1><p>Rat Detective</p></div></div><div class="capture"><span></span>Automatic capture on</div>{btn('settings','Settings','gear')}</header><div class="topline">{navigation()}<div class="filters"><label class="search">{icon('search')}<input type="search" placeholder="Search clips" aria-label="Search clips"></label>{picker('Filter by session',['All sessions','Today · 9:18 PM','Yesterday · 8:06 PM'],'session')}</div></div><div class="workspace">{library()}{viewer()}</div><footer class="app-footer"><span class="footer-count">6 clips · 2 favorites</span><span class="footer-hint">Choose a clip to watch</span><span>Local library</span></footer></div>'''
